  insert into public.recipe_translations (recipe_id, locale, owner_id, slug, title, summary, steps, tips, translation_status) values
    ('395caa3a-20d2-55f1-9ef6-ad2c21bfe191', 'tr', v_owner, 'menemen', 'Menemen', 'Domates, biber ve yumurta. On beş dakikada, tek tavada, klasik bir kahvaltı.', '["Biberleri ince halkalar hâlinde doğra; domateslerin kabuğunu soyup küp küp kes.","Zeytinyağını geniş bir tavada ısıt, biberleri 3–4 dakika yumuşayana kadar çevir.","Domatesleri ekle ve orta ateşte, suyunu biraz çekene kadar 5–6 dakika pişir.","Yumurtaları kır; ister bütün bırak ister hafifçe karıştır. Kıvamını bulunca ocaktan al.","Pul biber serp ve sıcak servis et."]'::jsonb, 'Soğanlı mı, soğansız mı? Tartışma hiç bitmez. Soğan eklersen biberlerle birlikte kavur.', 'needs_review'),
    ('395caa3a-20d2-55f1-9ef6-ad2c21bfe191', 'en', v_owner, 'menemen-turkish-scrambled-eggs', 'Menemen', 'Tomatoes, peppers and eggs. A classic Turkish breakfast in one pan and fifteen minutes.', '["Slice the peppers into thin rings; peel the tomatoes and dice them.","Warm the olive oil in a wide pan and cook the peppers for 3–4 minutes until soft.","Add the tomatoes and cook over medium heat for 5–6 minutes until slightly reduced.","Crack in the eggs; leave them whole or stir gently. Take off the heat once just set.","Sprinkle with chilli flakes and serve hot."]'::jsonb, 'Onion or no onion? The debate never ends. If you add it, cook it with the peppers.', 'needs_review'),
    ('395caa3a-20d2-55f1-9ef6-ad2c21bfe191', 'fr', v_owner, 'menemen-oeufs-brouilles-turcs', 'Menemen', 'Tomates, piments doux et œufs. Un petit-déjeuner turc classique, une poêle, quinze minutes.', '["Émince les piments en fines rondelles ; pèle les tomates et coupe-les en dés.","Chauffe l''huile d''olive dans une grande poêle et fais revenir les piments 3 à 4 minutes.","Ajoute les tomates et laisse cuire à feu moyen 5 à 6 minutes, jusqu’à légère réduction.","Casse les œufs ; laisse-les entiers ou mélange doucement. Retire du feu dès qu’ils sont pris.","Parsème de piment en flocons et sers chaud."]'::jsonb, 'Avec ou sans oignon ? Le débat est éternel. Si tu en mets, fais-le revenir avec les piments.', 'needs_review'),
    ('395caa3a-20d2-55f1-9ef6-ad2c21bfe191', 'ar', v_owner, 'mnemen', 'منمن', 'طماطم وفلفل وبيض. فطور تركي كلاسيكي في مقلاة واحدة وخلال ربع ساعة.', '["قطّع الفلفل حلقات رفيعة، وقشّر الطماطم وقطّعها مكعبات.","سخّن زيت الزيتون في مقلاة واسعة، وقلّب الفلفل 3–4 دقائق حتى يلين.","أضف الطماطم واطهها على نار متوسطة 5–6 دقائق حتى تتكاثف قليلًا.","اكسر البيض، واتركه كاملًا أو قلّبه برفق. ارفعه عن النار حين يتماسك.","رشّ الفلفل الأحمر المجروش وقدّمه ساخنًا."]'::jsonb, 'بالبصل أم بدونه؟ نقاش لا ينتهي. إن أضفته، فقلّبه مع الفلفل.', 'needs_review'),
    ('df15333a-90d0-5b10-8011-89bbb352c405', 'tr', v_owner, 'kirmizi-mercimek-corbasi', 'Kırmızı mercimek çorbası', 'Her mutfağın güvencesi. Lif ve bitkisel protein kaynağı, limonla parlayan kadifemsi bir çorba.', '["Mercimeği birkaç kez yıka ve süz.","Soğanı ve havucu küçük doğra; zeytinyağında 5 dakika, yumuşayana kadar kavur.","Salçayı ve kimyonu ekle, bir dakika çevir.","Mercimeği ve 1,5 litre sıcak suyu ekle. Kapağı aralık, mercimek dağılana kadar yaklaşık 25 dakika pişir.","Blenderdan geçir; kıvamını suyla ayarla ve tuzunu kontrol et.","Limonla servis et."]'::jsonb, 'Fazlasını porsiyonlayıp dondurabilirsin; üç aya kadar saklanır.', 'needs_review'),
    ('df15333a-90d0-5b10-8011-89bbb352c405', 'en', v_owner, 'red-lentil-soup', 'Red lentil soup', 'Every Turkish kitchen’s safe bet. A velvety soup with fibre and plant protein, brightened with lemon.', '["Rinse the lentils a few times and drain.","Finely chop the onion and carrot; soften them in the olive oil for 5 minutes.","Add the tomato paste and cumin and stir for a minute.","Add the lentils and 1.5 litres of hot water. With the lid ajar, simmer for about 25 minutes until the lentils fall apart.","Blend; adjust the thickness with water and check the salt.","Serve with lemon."]'::jsonb, 'Portion and freeze the leftovers; they keep for up to three months.', 'needs_review'),
    ('df15333a-90d0-5b10-8011-89bbb352c405', 'fr', v_owner, 'soupe-de-lentilles-corail', 'Soupe de lentilles corail', 'La valeur sûre des cuisines turques. Une soupe veloutée, source de fibres et de protéines végétales, relevée de citron.', '["Rince les lentilles plusieurs fois et égoutte-les.","Hache finement l''oignon et la carotte ; fais-les revenir 5 minutes dans l''huile d''olive.","Ajoute le concentré de tomate et le cumin, mélange une minute.","Ajoute les lentilles et 1,5 litre d''eau chaude. Couvercle entrouvert, laisse mijoter environ 25 minutes, jusqu''à ce que les lentilles se défassent.","Mixe ; ajuste la consistance avec de l''eau et rectifie le sel.","Sers avec du citron."]'::jsonb, 'Congèle les restes en portions ; ils se conservent jusqu''à trois mois.', 'needs_review'),
    ('df15333a-90d0-5b10-8011-89bbb352c405', 'ar', v_owner, 'shorbat-adas-ahmar', 'شوربة العدس الأحمر', 'الخيار المضمون في كل مطبخ. شوربة مخملية غنية بالألياف والبروتين النباتي، يزيّنها الليمون.', '["اغسل العدس عدة مرات وصفّه.","افرم البصل والجزر ناعمًا، وقلّبهما في زيت الزيتون 5 دقائق حتى يلينا.","أضف معجون الطماطم والكمون وقلّب دقيقة.","أضف العدس و1.5 لتر من الماء الساخن. اتركه يغلي بهدوء والغطاء مفتوح قليلًا نحو 25 دقيقة حتى يتفتت العدس.","اهرسه بالخلاط، واضبط القوام بالماء وتذوّق الملح.","قدّمه مع الليمون."]'::jsonb, 'قسّم الباقي إلى حصص وجمّده؛ يُحفظ حتى ثلاثة أشهر.', 'needs_review'),
    ('23c9cd4c-4d42-5a1c-84a4-7ba0815d98a0', 'tr', v_owner, 'nohutlu-kinoa-salatasi', 'Nohutlu kinoa salatası', 'Kısır ile çoban salatasının buluştuğu nokta: nar, sumak, bol yeşillik ve doyurucu nohut.', '["Kinoayı ince süzgeçte yıka. İki katı suyla 12–15 dakika, suyunu çekene kadar pişir ve soğut.","Salatalığı ve domatesi küçük küp doğra; maydanozu ve taze soğanı ince kıy.","Limon suyu, zeytinyağı, sumak ve bir tutam tuzla sosu çırp.","Kinoa, nohut ve sebzeleri sosla karıştır; narı en son serp."]'::jsonb, 'Ertesi günün öğle yemeği için sosunu ayrı taşı; salata dağılmaz.', 'needs_review'),
    ('23c9cd4c-4d42-5a1c-84a4-7ba0815d98a0', 'en', v_owner, 'chickpea-quinoa-salad', 'Chickpea & quinoa salad', 'Where kısır meets shepherd’s salad: pomegranate, sumac, plenty of herbs and filling chickpeas.', '["Rinse the quinoa in a fine sieve. Cook in twice its volume of water for 12–15 minutes until absorbed, then cool.","Dice the cucumber and tomato; finely chop the parsley and spring onions.","Whisk the lemon juice, olive oil, sumac and a pinch of salt into a dressing.","Toss the quinoa, chickpeas and vegetables with the dressing; scatter the pomegranate last."]'::jsonb, 'Packing it for tomorrow’s lunch? Carry the dressing separately so the salad stays crisp.', 'needs_review'),
    ('23c9cd4c-4d42-5a1c-84a4-7ba0815d98a0', 'fr', v_owner, 'salade-quinoa-pois-chiches', 'Salade de quinoa aux pois chiches', 'À la rencontre du kısır et de la salade du berger : grenade, sumac, beaucoup d’herbes et des pois chiches rassasiants.', '["Rince le quinoa dans une passoire fine. Fais-le cuire 12 à 15 minutes dans deux fois son volume d''eau, puis laisse refroidir.","Coupe le concombre et la tomate en petits dés ; cisèle le persil et l''oignon nouveau.","Fouette le jus de citron, l''huile d''olive, le sumac et une pincée de sel.","Mélange quinoa, pois chiches et légumes avec la sauce ; ajoute la grenade à la fin."]'::jsonb, 'Pour le déjeuner du lendemain, transporte la sauce à part : la salade reste croquante.', 'needs_review'),
    ('23c9cd4c-4d42-5a1c-84a4-7ba0815d98a0', 'ar', v_owner, 'salatat-kinwa-bil-hummus', 'سلطة الكينوا بالحمّص', 'حيث تلتقي الكِسِر بسلطة الراعي: رمّان وسمّاق وأعشاب وفيرة وحمّص مُشبع.', '["اغسل الكينوا في مصفاة ناعمة، واطهها بضعف حجمها من الماء 12–15 دقيقة حتى تتشرب الماء، ثم بردها.","قطّع الخيار والطماطم مكعبات صغيرة، وافرم البقدونس والبصل الأخضر ناعمًا.","اخفق عصير الليمون وزيت الزيتون والسماق مع رشة ملح.","اخلط الكينوا والحمّص والخضار مع الصلصة، ورشّ الرمّان في النهاية."]'::jsonb, 'إن أخذتها لغداء الغد، فاحمل الصلصة منفصلة كي تبقى السلطة مقرمشة.', 'needs_review'),
    ('23d45a3e-ec05-5547-a44b-01fe1b82523c', 'tr', v_owner, 'firinda-limonlu-somon-ve-kabak', 'Fırında limonlu somon ve kabak', 'Tek tepsi, yirmi dakika. Dereotu ve limonla, bulaşığı az bir akşam yemeği.', '["Fırını 200 °C’ye ısıt. Kabakları uzunlamasına dörde bölüp iri parçalar hâlinde kes.","Kabakları zeytinyağı, ezilmiş sarımsak ve bir tutam tuzla tepside harmanla; 8 dakika pişir.","Somonları tepsiye yerleştir, üzerine limon dilimleri koy.","Balık kolayca lif lif ayrılana kadar 10–12 dakika daha pişir.","Kıyılmış dereotu ve kalan limonun suyuyla servis et."]'::jsonb, 'Somon yerine levrek de olur; pişirme süresini 2–3 dakika kısalt.', 'needs_review'),
    ('23d45a3e-ec05-5547-a44b-01fe1b82523c', 'en', v_owner, 'baked-lemon-salmon-courgette', 'Baked lemon salmon with courgette', 'One tray, twenty minutes. A dinner with dill, lemon and very little washing-up.', '["Heat the oven to 200 °C. Quarter the courgettes lengthways and cut into chunks.","Toss the courgettes on the tray with olive oil, crushed garlic and a pinch of salt; roast for 8 minutes.","Nestle the salmon on the tray and top with lemon slices.","Roast for another 10–12 minutes until the fish flakes easily.","Serve with chopped dill and the juice of the remaining lemon."]'::jsonb, 'Sea bass works too; cut the cooking time by 2–3 minutes.', 'needs_review'),
    ('23d45a3e-ec05-5547-a44b-01fe1b82523c', 'fr', v_owner, 'saumon-au-citron-et-courgettes-au-four', 'Saumon au citron et courgettes au four', 'Une plaque, vingt minutes. Un dîner à l’aneth et au citron, avec très peu de vaisselle.', '["Préchauffe le four à 200 °C. Coupe les courgettes en quatre dans la longueur, puis en tronçons.","Mélange les courgettes sur la plaque avec l''huile d''olive, l''ail écrasé et une pincée de sel ; enfourne 8 minutes.","Dispose le saumon sur la plaque et couvre de rondelles de citron.","Poursuis la cuisson 10 à 12 minutes, jusqu''à ce que le poisson s''effeuille facilement.","Sers avec l’aneth ciselé et le jus du citron restant."]'::jsonb, 'Le bar convient aussi ; réduis la cuisson de 2 à 3 minutes.', 'needs_review'),
    ('23d45a3e-ec05-5547-a44b-01fe1b82523c', 'ar', v_owner, 'salmon-bil-laymun-wa-kusa-fil-furn', 'سلمون بالليمون مع الكوسا في الفرن', 'صينية واحدة وعشرون دقيقة. عشاء بالشبت والليمون وقليل من الجلي.', '["سخّن الفرن إلى 200 °م. اقسم الكوسا طوليًا إلى أربعة ثم قطّعها قطعًا كبيرة.","اخلط الكوسا في الصينية مع زيت الزيتون والثوم المهروس ورشة ملح، واخبزها 8 دقائق.","ضع قطع السلمون في الصينية وفوقها شرائح الليمون.","اخبز 10–12 دقيقة أخرى حتى تتفكك السمكة بسهولة.","قدّمها مع الشبت المفروم وعصير الليمونة المتبقية."]'::jsonb, 'يصلح القاروص أيضًا؛ قلّل وقت الطهي 2–3 دقائق.', 'needs_review'),
    ('9b0af6b0-397a-50ab-927d-8a627c1cb983', 'tr', v_owner, 'gece-bekletilen-yulaf', 'Süzme yoğurtlu gece yulafı', 'Akşamdan beş dakika, sabah sıfır dakika. Cevizli, narlı ve tarçınlı bir kavanoz kahvaltı.', '["Yulafı, süzme yoğurdu, tarçını ve 3–4 yemek kaşığı suyu bir kavanozda karıştır.","Kapağını kapatıp buzdolabında en az 6 saat, tercihen bir gece beklet.","Sabah kıvamını bir kaşık suyla aç; üzerine ceviz ve nar ekle."]'::jsonb, 'Tatlı istersen balı ekle; tarçın ve nar çoğu zaman yeterince tat verir.', 'needs_review'),
    ('9b0af6b0-397a-50ab-927d-8a627c1cb983', 'en', v_owner, 'overnight-oats-strained-yoghurt', 'Overnight oats with strained yoghurt', 'Five minutes the night before, zero in the morning. A jar breakfast with walnuts, pomegranate and cinnamon.', '["Stir the oats, strained yoghurt, cinnamon and 3–4 tablespoons of water together in a jar.","Close the lid and refrigerate for at least 6 hours, ideally overnight.","In the morning loosen with a spoonful of water; top with walnuts and pomegranate."]'::jsonb, 'Add the honey if you like it sweeter; cinnamon and pomegranate usually do the job.', 'needs_review'),
    ('9b0af6b0-397a-50ab-927d-8a627c1cb983', 'fr', v_owner, 'flocons-davoine-de-la-veille-au-yaourt', 'Flocons d’avoine de la veille au yaourt égoutté', 'Cinq minutes la veille, zéro le matin. Un petit-déjeuner en bocal aux noix, à la grenade et à la cannelle.', '["Mélange les flocons, le yaourt égoutté, la cannelle et 3 à 4 cuillères à soupe d''eau dans un bocal.","Ferme et laisse au réfrigérateur au moins 6 heures, idéalement toute la nuit.","Le matin, détends avec une cuillère d''eau ; ajoute les noix et la grenade."]'::jsonb, 'Ajoute le miel si tu veux plus sucré ; la cannelle et la grenade suffisent souvent.', 'needs_review'),
    ('9b0af6b0-397a-50ab-927d-8a627c1cb983', 'ar', v_owner, 'shufan-al-layl-bil-labna', 'شوفان منقوع مع اللبنة', 'خمس دقائق في المساء ولا شيء في الصباح. فطور في مرطبان مع الجوز والرمّان والقرفة.', '["اخلط الشوفان واللبنة والقرفة و3–4 ملاعق كبيرة من الماء في مرطبان.","أغلقه واتركه في الثلاجة 6 ساعات على الأقل، ويفضَّل طوال الليل.","في الصباح خفّف القوام بملعقة ماء، وأضف الجوز والرمّان."]'::jsonb, 'أضف العسل إن أردته أحلى؛ القرفة والرمّان يكفيان غالبًا.', 'needs_review'),
    ('343786d4-823f-5280-9ae9-f8486571051b', 'tr', v_owner, 'zeytinyagli-taze-fasulye', 'Zeytinyağlı taze fasulye', 'Oda sıcaklığında daha da güzel. Ege mutfağının sabırla pişen, sade klasiği.', '["Fasulyelerin uçlarını ayıkla, ikiye ya da üçe böl.","Soğanı yarım ay doğra; zeytinyağında şeffaflaşana kadar kavur.","Fasulyeleri ekle, 5 dakika çevir. Rendelenmiş domatesi ve yarım su bardağı sıcak suyu ekle.","Kapağını kapat, kısık ateşte fasulyeler yumuşayana kadar 30–35 dakika pişir.","Tencerede ılımaya bırak; oda sıcaklığında servis et."]'::jsonb, 'Yanına yoğurt ve bir dilim tam buğday ekmeği koyarsan dengeli bir öğün olur.', 'needs_review'),
    ('343786d4-823f-5280-9ae9-f8486571051b', 'en', v_owner, 'green-beans-in-olive-oil', 'Green beans in olive oil', 'Even better at room temperature. A slow-cooked, simple classic of the Aegean kitchen.', '["Top and tail the beans and cut into two or three pieces.","Slice the onion into half-moons; soften in the olive oil until translucent.","Add the beans and stir for 5 minutes. Add the grated tomatoes and half a glass of hot water.","Cover and cook over low heat for 30–35 minutes until the beans are tender.","Let it cool in the pot; serve at room temperature."]'::jsonb, 'Add yoghurt and a slice of wholemeal bread on the side for a balanced meal.', 'needs_review'),
    ('343786d4-823f-5280-9ae9-f8486571051b', 'fr', v_owner, 'haricots-verts-a-lhuile-dolive', 'Haricots verts à l’huile d’olive', 'Encore meilleurs à température ambiante. Un classique simple et mijoté de la cuisine égéenne.', '["Équeute les haricots et coupe-les en deux ou trois.","Émince l''oignon en demi-lunes ; fais-le fondre dans l''huile d''olive.","Ajoute les haricots, remue 5 minutes. Ajoute les tomates râpées et un demi-verre d''eau chaude.","Couvre et laisse cuire à feu doux 30 à 35 minutes, jusqu''à ce que les haricots soient tendres.","Laisse tiédir dans la casserole ; sers à température ambiante."]'::jsonb, 'Avec un yaourt et une tranche de pain complet, cela fait un repas équilibré.', 'needs_review'),
    ('343786d4-823f-5280-9ae9-f8486571051b', 'ar', v_owner, 'fasulya-khadra-bi-zayt-al-zaytun', 'فاصوليا خضراء بزيت الزيتون', 'ألذّ في حرارة الغرفة. طبق بسيط يُطهى على مهل من مطبخ بحر إيجة.', '["نظّف أطراف الفاصوليا واقطعها إلى قطعتين أو ثلاث.","قطّع البصل أنصاف حلقات وقلّبه في زيت الزيتون حتى يصبح شفافًا.","أضف الفاصوليا وقلّب 5 دقائق، ثم أضف الطماطم المبشورة ونصف كوب ماء ساخن.","غطِّ القدر واطهُ على نار هادئة 30–35 دقيقة حتى تطرى الفاصوليا.","اتركها تفتر في القدر، وقدّمها في حرارة الغرفة."]'::jsonb, 'مع اللبن وشريحة خبز من القمح الكامل تصبح وجبة متوازنة.', 'needs_review'),
    ('2ecdbc53-5e3d-59b5-b223-0f8cb3e8f0e4', 'tr', v_owner, 'sebzeli-nohutlu-bulgur-pilavi', 'Sebzeli, nohutlu bulgur pilavı', 'Tane tane, salçalı ve lifli. Kendi başına öğün, yanına yoğurtla tam bir sofra.', '["Soğanı ve biberi küçük doğra; zeytinyağında 5 dakika kavur.","Biber salçasını ve rendelenmiş domatesi ekle, 2 dakika çevir.","Bulguru ve nohudu ekle, yağla kaplanması için bir dakika karıştır.","İki su bardağı sıcak su ve tuz ekle. Kaynayınca kısık ateşte suyunu çekene kadar 15 dakika pişir.","Ocaktan al, kapağın altına kâğıt havlu koyup 10 dakika demlendir."]'::jsonb, 'Ayranla ya da cacıkla servis et.', 'needs_review'),
    ('2ecdbc53-5e3d-59b5-b223-0f8cb3e8f0e4', 'en', v_owner, 'bulgur-pilaf-with-vegetables-and-chickpeas', 'Bulgur pilaf with vegetables & chickpeas', 'Fluffy, peppery and full of fibre. A meal on its own, or a full table with yoghurt.', '["Finely chop the onion and pepper; cook in the olive oil for 5 minutes.","Add the pepper paste and grated tomato; stir for 2 minutes.","Add the bulgur and chickpeas and stir for a minute to coat.","Add two glasses of hot water and salt. Bring to the boil, then simmer on low for 15 minutes until absorbed.","Off the heat, put a paper towel under the lid and let it rest for 10 minutes."]'::jsonb, 'Serve with ayran or cacık.', 'needs_review'),
    ('2ecdbc53-5e3d-59b5-b223-0f8cb3e8f0e4', 'fr', v_owner, 'pilaf-de-boulgour-aux-legumes-et-pois-chiches', 'Pilaf de boulgour aux légumes et pois chiches', 'Grains détachés, parfumé au piment et riche en fibres. Un repas à lui seul, ou une table complète avec du yaourt.', '["Hache l''oignon et le poivron ; fais-les revenir 5 minutes dans l''huile d''olive.","Ajoute la purée de piment et la tomate râpée ; remue 2 minutes.","Ajoute le boulgour et les pois chiches, mélange une minute pour bien les enrober.","Ajoute deux verres d''eau chaude et le sel. À ébullition, baisse le feu et laisse cuire 15 minutes jusqu''à absorption.","Hors du feu, glisse un essuie-tout sous le couvercle et laisse reposer 10 minutes."]'::jsonb, 'Sers avec de l’ayran ou du cacık.', 'needs_review'),
    ('2ecdbc53-5e3d-59b5-b223-0f8cb3e8f0e4', 'ar', v_owner, 'burghul-bil-khudar-wal-hummus', 'برغل بالخضار والحمّص', 'حبات منفصلة ونكهة الفلفل وغنى بالألياف. وجبة بحد ذاتها، ومع اللبن مائدة كاملة.', '["افرم البصل والفلفل ناعمًا، وقلّبهما في زيت الزيتون 5 دقائق.","أضف دبس الفلفل والطماطم المبشورة، وقلّب دقيقتين.","أضف البرغل والحمّص، وقلّب دقيقة حتى يتغلفا بالزيت.","أضف كوبين من الماء الساخن والملح. عند الغليان اخفض النار واطهُ 15 دقيقة حتى يتشرب الماء.","ارفعه عن النار، وضع منديلًا ورقيًا تحت الغطاء، واتركه يرتاح 10 دقائق."]'::jsonb, 'قدّمه مع العيران أو الجاجيك.', 'needs_review'),
    ('b9507c06-8136-5950-bcd1-120f57d33429', 'tr', v_owner, 'tavuklu-sebze-sote', 'Tavuklu sebze sote', 'Yüksek ateş, kısa süre. Proteini bol, renkli ve on beş dakikada tabakta.', '["Tavuğu kuşbaşı doğra; sebzeleri benzer büyüklükte kes.","Geniş tavayı iyice ısıt, zeytinyağını ekle ve tavuğu tek kat hâlinde 5–6 dakika, her yanı renk alana kadar pişir.","Soğanı, biberi ve mantarı ekle; 4 dakika yüksek ateşte çevir.","Kabağı ve sarımsağı ekle, 3 dakika daha pişir. Tuz ve pul biberle tatlandır."]'::jsonb, 'Tavayı kalabalık etme; sebzeler buharda pişmek yerine kavrulsun.', 'needs_review'),
    ('b9507c06-8136-5950-bcd1-120f57d33429', 'en', v_owner, 'chicken-vegetable-saute', 'Chicken & vegetable sauté', 'High heat, short time. Protein-rich, colourful and on the plate in fifteen minutes.', '["Dice the chicken; cut the vegetables to a similar size.","Heat a wide pan well, add the olive oil and cook the chicken in a single layer for 5–6 minutes until coloured all over.","Add the onion, pepper and mushrooms; stir-fry over high heat for 4 minutes.","Add the courgette and garlic and cook 3 more minutes. Season with salt and chilli flakes."]'::jsonb, 'Don’t crowd the pan; you want the vegetables to sear, not steam.', 'needs_review'),
    ('b9507c06-8136-5950-bcd1-120f57d33429', 'fr', v_owner, 'poulet-saute-aux-legumes', 'Poulet sauté aux légumes', 'Feu vif, cuisson courte. Riche en protéines, coloré et dans l’assiette en quinze minutes.', '["Coupe le poulet en cubes et les légumes en morceaux de taille similaire.","Chauffe bien une grande poêle, ajoute l''huile d''olive et saisis le poulet en une seule couche 5 à 6 minutes, jusqu''à coloration.","Ajoute l''oignon, le poivron et les champignons ; fais sauter 4 minutes à feu vif.","Ajoute la courgette et l''ail, poursuis 3 minutes. Assaisonne de sel et de piment en flocons."]'::jsonb, 'Ne surcharge pas la poêle : les légumes doivent saisir, pas cuire à la vapeur.', 'needs_review'),
    ('b9507c06-8136-5950-bcd1-120f57d33429', 'ar', v_owner, 'dajaj-mushawwah-bil-khudar', 'دجاج مشوّح بالخضار', 'نار عالية ووقت قصير. غني بالبروتين وملوّن وجاهز خلال ربع ساعة.', '["قطّع الدجاج مكعبات، والخضار بحجم مماثل.","سخّن مقلاة واسعة جيدًا، وأضف زيت الزيتون، واطهُ الدجاج في طبقة واحدة 5–6 دقائق حتى يتحمّر من كل الجهات.","أضف البصل والفلفل والفطر، وقلّب على نار عالية 4 دقائق.","أضف الكوسا والثوم واطهُ 3 دقائق أخرى. تبّل بالملح والفلفل المجروش."]'::jsonb, 'لا تملأ المقلاة أكثر من اللازم؛ نريد أن تتحمّر الخضار لا أن تُطهى بالبخار.', 'needs_review'),
    ('e7fbf28f-0734-55d3-b1fd-e1f54b181c7d', 'tr', v_owner, 'cilbir', 'Çılbır', 'Sarımsaklı yoğurdun üstünde poşe yumurta ve pul biberli tereyağı. Osmanlı mutfağından bir hafta sonu kahvaltısı.', '["Yoğurdu ezilmiş sarımsak ve bir tutam tuzla çırp; oda sıcaklığına gelsin diye tabaklara paylaştır.","Geniş bir tencerede suyu hafif kaynama noktasına getir, bir kaşık sirke ekle.","Yumurtaları tek tek bir kaseye kırıp suya kaydır; 3 dakika poşe et ve delikli kepçeyle al.","Yumurtaları yoğurdun üzerine yerleştir.","Tereyağını eritip pul biberi ekle, köpürünce yumurtaların üzerine gezdir."]'::jsonb, 'Suyu fokurdatma; hafif titreyen su yumurtanın beyazını toplu tutar.', 'needs_review'),
    ('e7fbf28f-0734-55d3-b1fd-e1f54b181c7d', 'en', v_owner, 'cilbir-turkish-eggs', 'Çılbır (Turkish eggs)', 'Poached eggs on garlicky yoghurt with chilli butter. A weekend breakfast from the Ottoman kitchen.', '["Whisk the yoghurt with crushed garlic and a pinch of salt; divide between plates so it comes to room temperature.","Bring a wide pan of water to a gentle simmer and add a spoonful of vinegar.","Crack each egg into a cup and slide it into the water; poach for 3 minutes and lift out with a slotted spoon.","Place the eggs on the yoghurt.","Melt the butter with the chilli flakes and, once foaming, drizzle it over the eggs."]'::jsonb, 'Don’t let the water bubble hard; a gentle shiver keeps the whites together.', 'needs_review'),
    ('e7fbf28f-0734-55d3-b1fd-e1f54b181c7d', 'fr', v_owner, 'cilbir-oeufs-a-la-turque', 'Çılbır (œufs à la turque)', 'Œufs pochés sur yaourt à l’ail et beurre pimenté. Un petit-déjeuner du week-end hérité de la cuisine ottomane.', '["Fouette le yaourt avec l''ail écrasé et une pincée de sel ; répartis-le dans les assiettes pour qu''il soit à température ambiante.","Porte une grande casserole d''eau à frémissement et ajoute une cuillère de vinaigre.","Casse chaque œuf dans une tasse et fais-le glisser dans l''eau ; poche 3 minutes puis retire à l''écumoire.","Dépose les œufs sur le yaourt.","Fais fondre le beurre avec le piment et, dès qu’il mousse, verse-le sur les œufs."]'::jsonb, 'Pas de gros bouillons : un léger frémissement garde les blancs bien regroupés.', 'needs_review'),
    ('e7fbf28f-0734-55d3-b1fd-e1f54b181c7d', 'ar', v_owner, 'chilbir', 'تشلبر', 'بيض مسلوق بلا قشر فوق لبن بالثوم مع زبدة بالفلفل. فطور عطلة من المطبخ العثماني.', '["اخفق اللبن مع الثوم المهروس ورشة ملح، ووزّعه على الأطباق ليصل إلى حرارة الغرفة.","سخّن الماء في قدر واسع حتى يقارب الغليان، وأضف ملعقة خل.","اكسر كل بيضة في كوب وأنزلها في الماء، واسلقها 3 دقائق ثم ارفعها بمغرفة مثقوبة.","ضع البيض فوق اللبن.","ذوّب الزبدة مع الفلفل المجروش، وحين تزبد صبّها فوق البيض."]'::jsonb, 'لا تدع الماء يغلي بشدة؛ الغليان الهادئ يحافظ على تماسك بياض البيض.', 'needs_review'),
    ('bda683e7-26ac-53ac-9486-de9ee4253c5f', 'tr', v_owner, 'firinda-baharatli-nohut', 'Fırında baharatlı nohut', 'Çıtır, baharatlı, lifli. Cips isteyen akşamlar için hazır bir kavanoz.', '["Fırını 200 °C’ye ısıt. Nohutları süz ve temiz bir bezle iyice kurula.","Zeytinyağı, kimyon, pul biber ve tuzla harmanla; tepsiye tek kat yay.","Arada bir sallayarak 25–30 dakika, çıtırlaşana kadar kızart.","Sumak serp, tepside soğumaya bırak."]'::jsonb, 'Tamamen soğuyunca ağzı kapalı kavanozda 3 gün çıtırlığını korur.', 'needs_review'),
    ('bda683e7-26ac-53ac-9486-de9ee4253c5f', 'en', v_owner, 'spiced-roasted-chickpeas', 'Spiced roasted chickpeas', 'Crunchy, spiced and full of fibre. A jar ready for the evenings that want crisps.', '["Heat the oven to 200 °C. Drain the chickpeas and dry them well with a clean towel.","Toss with olive oil, cumin, chilli flakes and salt; spread in a single layer on a tray.","Roast for 25–30 minutes, shaking now and then, until crisp.","Sprinkle with sumac and let them cool on the tray."]'::jsonb, 'Once fully cool, they stay crunchy in a sealed jar for 3 days.', 'needs_review'),
    ('bda683e7-26ac-53ac-9486-de9ee4253c5f', 'fr', v_owner, 'pois-chiches-rotis-aux-epices', 'Pois chiches rôtis aux épices', 'Croustillants, épicés et riches en fibres. Un bocal prêt pour les soirs d’envie de chips.', '["Préchauffe le four à 200 °C. Égoutte les pois chiches et sèche-les bien avec un torchon propre.","Mélange-les avec l''huile d''olive, le cumin, le piment et le sel ; étale-les en une couche sur une plaque.","Rôtis 25 à 30 minutes en secouant de temps en temps, jusqu''à ce qu''ils soient croustillants.","Saupoudre de sumac et laisse refroidir sur la plaque."]'::jsonb, 'Une fois bien refroidis, ils restent croustillants 3 jours dans un bocal fermé.', 'needs_review'),
    ('bda683e7-26ac-53ac-9486-de9ee4253c5f', 'ar', v_owner, 'hummus-muhammas-bil-baharat', 'حمّص محمّص بالبهارات', 'مقرمش ومتبّل وغني بالألياف. مرطبان جاهز للأمسيات التي تشتهي رقائق البطاطا.', '["سخّن الفرن إلى 200 °م. صفِّ الحمّص وجففه جيدًا بمنشفة نظيفة.","اخلطه بزيت الزيتون والكمون والفلفل المجروش والملح، وافرده طبقة واحدة في صينية.","حمّصه 25–30 دقيقة مع هز الصينية من حين لآخر حتى يصبح مقرمشًا.","رشّ السماق واتركه يبرد في الصينية."]'::jsonb, 'بعد أن يبرد تمامًا، يبقى مقرمشًا 3 أيام في مرطبان محكم.', 'needs_review'),
    ('68fecda7-80a2-5ad2-bee9-6059e478965a', 'tr', v_owner, 'mercimek-koftesi', 'Mercimek köftesi', 'Pişmeyen köfte: mercimeğin sıcaklığıyla demlenen bulgur, bol yeşillik, marul yaprağı ve limon.', '["Mercimeği 2,5 su bardağı suyla, dağılıp suyunu çekene kadar yaklaşık 20 dakika pişir.","Ocaktan alır almaz bulguru ekle, karıştır ve kapağı kapalı 20 dakika demlendir.","Soğanı ince doğrayıp zeytinyağında kavur; salçaları ekleyip bir dakika çevir.","Soğanlı karışımı, kimyonu ve tuzu mercimeğe ekleyip ılıyınca iyice yoğur.","Kıyılmış taze soğan ve maydanozu ekle; ıslak elle uzun köfteler şekillendir.","Marul yaprakları ve limonla servis et."]'::jsonb, 'Karışım kuru gelirse bir iki kaşık ılık su ekleyerek yoğur.', 'needs_review'),
    ('68fecda7-80a2-5ad2-bee9-6059e478965a', 'en', v_owner, 'red-lentil-kofte', 'Red lentil köfte', 'Köfte that never meets a pan: bulgur steamed by hot lentils, plenty of herbs, lettuce leaves and lemon.', '["Cook the lentils in 2.5 glasses of water for about 20 minutes until they break down and absorb it.","As soon as you take it off the heat, stir in the bulgur, cover and let it steam for 20 minutes.","Finely chop the onion and soften it in the olive oil; add both pastes and stir for a minute.","Add the onion mixture, cumin and salt to the lentils and knead well once warm.","Mix in the chopped spring onions and parsley; shape long köfte with wet hands.","Serve with lettuce leaves and lemon."]'::jsonb, 'If the mixture feels dry, knead in a spoonful or two of warm water.', 'needs_review'),
    ('68fecda7-80a2-5ad2-bee9-6059e478965a', 'fr', v_owner, 'kofte-de-lentilles-corail', 'Köfte de lentilles corail', 'Des köfte sans cuisson : boulgour gonflé à la chaleur des lentilles, beaucoup d’herbes, feuilles de laitue et citron.', '["Fais cuire les lentilles dans 2,5 verres d''eau environ 20 minutes, jusqu''à ce qu''elles se défassent et absorbent l''eau.","Dès la sortie du feu, ajoute le boulgour, mélange, couvre et laisse gonfler 20 minutes.","Hache finement l''oignon et fais-le revenir dans l''huile d''olive ; ajoute les deux concentrés et remue une minute.","Ajoute ce mélange, le cumin et le sel aux lentilles et pétris bien une fois tiède.","Incorpore l''oignon nouveau et le persil hachés ; façonne des köfte allongées avec les mains mouillées.","Sers avec des feuilles de laitue et du citron."]'::jsonb, 'Si la pâte est sèche, ajoute une ou deux cuillères d''eau tiède en pétrissant.', 'needs_review'),
    ('68fecda7-80a2-5ad2-bee9-6059e478965a', 'ar', v_owner, 'kufta-al-adas', 'كفتة العدس', 'كفتة لا تُطهى: برغل ينضج بحرارة العدس، وأعشاب وفيرة، وأوراق خس، وليمون.', '["اطهُ العدس في 2.5 كوب ماء نحو 20 دقيقة حتى يتفتت ويتشرب الماء.","فور رفعه عن النار أضف البرغل وقلّب، وغطِّه واتركه 20 دقيقة لينضج.","افرم البصل ناعمًا وقلّبه في زيت الزيتون، ثم أضف المعجونين وقلّب دقيقة.","أضف خليط البصل والكمون والملح إلى العدس، واعجنه جيدًا حين يفتر.","أضف البصل الأخضر والبقدونس المفرومين، وشكّل أقراصًا مستطيلة بيدين مبللتين.","قدّمها مع أوراق الخس والليمون."]'::jsonb, 'إن بدا الخليط جافًا، أضف ملعقة أو اثنتين من الماء الفاتر أثناء العجن.', 'needs_review'),
    ('ce6fe68f-4009-59ff-8481-923621dfc45e', 'tr', v_owner, 'elmali-tarcinli-suzme-yogurt', 'Elmalı, tarçınlı süzme yoğurt', 'İkindi açlığına beş dakikalık cevap: proteinli yoğurt, rendelenmiş elma, ceviz ve tarçın.', '["Elmayı kabuğuyla iri rendele.","Süzme yoğurdu kaseye al; elmayı, chia tohumunu ve tarçını ekle.","Üzerine kırılmış ceviz serp."]'::jsonb, 'Elmayı rendeledikten hemen sonra kullan ya da birkaç damla limon sık; kararmaz.', 'needs_review'),
    ('ce6fe68f-4009-59ff-8481-923621dfc45e', 'en', v_owner, 'strained-yoghurt-with-apple-and-cinnamon', 'Strained yoghurt with apple & cinnamon', 'A five-minute answer to afternoon hunger: protein-rich yoghurt, grated apple, walnuts and cinnamon.', '["Coarsely grate the apple, skin on.","Spoon the strained yoghurt into a bowl; add the apple, chia seeds and cinnamon.","Scatter the broken walnuts on top."]'::jsonb, 'Use the apple right after grating, or add a few drops of lemon so it doesn’t brown.', 'needs_review'),
    ('ce6fe68f-4009-59ff-8481-923621dfc45e', 'fr', v_owner, 'yaourt-egoutte-pomme-cannelle', 'Yaourt égoutté, pomme et cannelle', 'Une réponse en cinq minutes au creux de l’après-midi : yaourt riche en protéines, pomme râpée, noix et cannelle.', '["Râpe grossièrement la pomme avec la peau.","Verse le yaourt égoutté dans un bol ; ajoute la pomme, les graines de chia et la cannelle.","Parsème de noix concassées."]'::jsonb, 'Utilise la pomme aussitôt râpée, ou ajoute quelques gouttes de citron pour qu’elle ne noircisse pas.', 'needs_review'),
    ('ce6fe68f-4009-59ff-8481-923621dfc45e', 'ar', v_owner, 'labna-bil-tuffah-wal-qirfa', 'لبنة بالتفاح والقرفة', 'جواب في خمس دقائق لجوع العصر: لبنة غنية بالبروتين، وتفاح مبشور، وجوز، وقرفة.', '["ابشر التفاحة بقشرها بشرًا خشنًا.","ضع اللبنة في وعاء، وأضف التفاح وبذور الشيا والقرفة.","رشّ الجوز المكسّر على الوجه."]'::jsonb, 'استخدم التفاح فور بشره، أو أضف قطرات ليمون كي لا يسودّ.', 'needs_review'),
    ('0a9df7e3-db0f-5cd9-b3c0-adee7b81f04c', 'tr', v_owner, 'ton-balikli-piyaz', 'Ton balıklı piyaz', 'Pişirmesiz, on dakikalık, doyurucu bir öğle yemeği. Proteini ve lifi bol, sumaklı bir klasik.', '["Soğanı piyazlık doğra, sumak ve bir tutam tuzla ovup 5 dakika beklet.","Fasulyeyi süzüp yıka; ton balığının suyunu süz.","Domatesi küp doğra, maydanozu kıy.","Hepsini limon suyu ve zeytinyağıyla nazikçe karıştır; ton balığını en son, iri parçalar hâlinde ekle."]'::jsonb, 'Antalya usulü istersen bir yemek kaşığı tahini limonla açıp sosa ekle.', 'needs_review'),
    ('0a9df7e3-db0f-5cd9-b3c0-adee7b81f04c', 'en', v_owner, 'tuna-and-white-bean-piyaz', 'Tuna & white bean piyaz', 'No cooking, ten minutes, genuinely filling. A sumac-bright classic rich in protein and fibre.', '["Slice the onion thinly, rub with sumac and a pinch of salt and leave for 5 minutes.","Drain and rinse the beans; drain the tuna.","Dice the tomato and chop the parsley.","Fold everything gently with the lemon juice and olive oil; add the tuna last, in large flakes."]'::jsonb, 'For the Antalya style, loosen a tablespoon of tahini with lemon and stir it into the dressing.', 'needs_review'),
    ('0a9df7e3-db0f-5cd9-b3c0-adee7b81f04c', 'fr', v_owner, 'piyaz-au-thon-et-haricots-blancs', 'Piyaz au thon et haricots blancs', 'Sans cuisson, dix minutes, vraiment rassasiant. Un classique au sumac, riche en protéines et en fibres.', '["Émince finement l''oignon, frotte-le avec le sumac et une pincée de sel et laisse reposer 5 minutes.","Égoutte et rince les haricots ; égoutte le thon.","Coupe la tomate en dés et hache le persil.","Mélange délicatement le tout avec le jus de citron et l''huile d''olive ; ajoute le thon en dernier, en gros morceaux."]'::jsonb, 'Façon Antalya : détends une cuillère à soupe de tahini avec du citron et ajoute-la à la sauce.', 'needs_review'),
    ('0a9df7e3-db0f-5cd9-b3c0-adee7b81f04c', 'ar', v_owner, 'piyaz-bil-tuna', 'بياز بالتونة', 'بلا طهي وفي عشر دقائق ومُشبع حقًا. طبق كلاسيكي بالسماق غني بالبروتين والألياف.', '["قطّع البصل شرائح رفيعة، وافركه بالسماق ورشة ملح، واتركه 5 دقائق.","صفِّ الفاصوليا واغسلها، وصفِّ التونة.","قطّع الطماطم مكعبات وافرم البقدونس.","اخلط الجميع برفق مع عصير الليمون وزيت الزيتون، وأضف التونة في النهاية قطعًا كبيرة."]'::jsonb, 'على طريقة أنطاليا: خفّف ملعقة كبيرة من الطحينة بالليمون وأضفها إلى الصلصة.', 'needs_review')
